mapper.select:
SELECT
FROM goods_spu INNER JOIN ship_goods_profile profile ON profile.spu_id = goods_spu.id AND profile.tenant_id = goods_spu.tenant_id AND profile.del_flag = '0' LEFT JOIN ship_sku_profile sku_profile ON sku_profile.spu_id = goods_spu.id AND sku_profile.tenant_id = goods_spu.tenant_id AND sku_profile.del_flag = '0' LEFT JOIN goods_sku ON goods_sku.id = sku_profile.sku_id AND goods_sku.tenant_id = goods_spu.tenant_id AND goods_sku.del_flag = '0' WHERE goods_spu.tenant_id = #{tenantId} AND goods_spu.del_flag = '0'
AND profile.sale_scope = #{query.saleScope}
AND profile.sale_scope IN ('2', '3')
AND (profile.impa_code LIKE CONCAT('%', #{query.impaCode}, '%') OR profile.issa_code LIKE CONCAT('%', #{query.impaCode}, '%') OR profile.internal_item_code LIKE CONCAT('%', #{query.impaCode}, '%') OR profile.barcode LIKE CONCAT('%', #{query.impaCode}, '%'))
AND (profile.name_en LIKE CONCAT('%', #{query.nameEn}, '%') OR goods_spu.name LIKE CONCAT('%', #{query.nameEn}, '%') OR profile.search_aliases LIKE CONCAT('%', #{query.nameEn}, '%'))
AND profile.storage_type = #{query.storageType}
AND goods_spu.`status` = #{query.status}
AND sku_profile.moq >= #{query.moq}
AND profile.publish_completeness <= #{query.publishCompleteness}
ORDER BY goods_spu.create_time DESC
